export function resolveSample(theme,id){const list=Object.hasOwn(studyCatalog,theme)?studyCatalog[theme]:studyCatalog.oil;const index=Math.max(0,list.findIndex(item=>item[0]===id));return{id:list[index][0],name:list[index][1],index};}
export function allStudies(){return Object.entries(studyCatalog).flatMap(([theme,list])=>list.map(([id,name],index)=>({theme,id,name,index})));}
